function buildFeatures(p) {
    const age = p.age == null ? DATA.medAge[p.title] : p.age, fare = p.fare == null ? DATA.medFare : p.fare, fam = p.sibsp + p.parch + 1;
    const f = {
        Pclass: p.pclass, Sex: p.sex === 'female' ? 1 : 0, Age: age, SibSp: p.sibsp, Parch: p.parch, Fare: fare, FamilySize: fam,
        IsAlone: fam === 1 ? 1 : 0, HasCabin: p.cabin, Embarked_Q: p.emb === 'Q' ? 1 : 0, Embarked_S: p.emb === 'S' ? 1 : 0,
        Title_Miss: p.title === 'Miss' ? 1 : 0, Title_Mr: p.title === 'Mr' ? 1 : 0, Title_Mrs: p.title === 'Mrs' ? 1 : 0, Title_Rare: p.title === 'Rare' ? 1 : 0
    };
    return DATA.cols.map(c => f[c]);
}
function predictProb(x) {
    let s = 0;
    for (const t of DATA.trees) { let n = 0; while (t.l[n] !== -1) { n = x[t.f[n]] <= t.t[n] ? t.l[n] : t.r[n]; } s += t.v[n]; }
    return 1 / (1 + Math.exp(-(DATA.init + DATA.lr * s)));
}
function survivalChance(p) { return predictProb(buildFeatures(p)); }

const $ = id => document.getElementById(id);
const read = () => { const n = i => { const e = $(i), v = parseFloat(e.value); return isNaN(v) ? null : Math.min(Math.max(v, +e.min), +e.max) }; return { title: $('title').value, sex: $('sex').value, age: n('age'), pclass: parseInt($('pclass').value), sibsp: Math.max(0, n('sibsp') || 0), parch: Math.max(0, n('parch') || 0), fare: n('fare'), emb: $('emb').value, cabin: $('cabin').checked ? 1 : 0 }; };
$('title').onchange = () => { const t = $('title').value; if (t === 'Mr' || t === 'Master') $('sex').value = 'male'; if (t === 'Mrs' || t === 'Miss') $('sex').value = 'female'; };
let last = '';
function run() {
    const p = read(), c = survivalChance(p), pc = Math.round(c * 100), ok = c >= .5;
    $('empty').style.display = 'none'; $('res').style.display = 'block';
    $('ring').style.setProperty('--p', pc); $('ring').style.setProperty('--c', ok ? 'var(--good)' : 'var(--bad)'); $('pct').textContent = pc + '%';
    $('verdict').textContent = ok ? 'Would likely SURVIVE' : 'Would likely NOT survive'; $('verdict').style.color = ok ? 'var(--good)' : 'var(--bad)';
    $('sub').textContent = 'Estimated chance of survival: ' + pc + '%. Above 50% counts as "survive".';
    $('bars').innerHTML = [1, 2, 3].map(k => { const v = Math.round(survivalChance({ ...p, pclass: k }) * 100); return `<div class="bar${k === p.pclass ? ' me' : ''}"><span>${['1st', '2nd', '3rd'][k - 1]} class</span><div class="t"><i data-w="${v}"></i></div><b>${v}%</b></div>` }).join('');
    requestAnimationFrame(() => document.querySelectorAll('#bars i').forEach(i => i.style.width = i.dataset.w + '%'));
    const m = p.sex === 'male', o = Math.round(survivalChance({ ...p, sex: m ? 'female' : 'male', title: m ? 'Miss' : 'Mr' }) * 100);
    $('what').textContent = 'What if the passenger were ' + (m ? 'a woman' : 'a man') + '? The estimate would be about ' + o + '%.';
    drawCurve(p); last = 'Titanic survival estimate: ' + pc + '% (' + (ok ? 'would likely survive' : 'would likely not survive') + '). ' + p.sex + ', class ' + p.pclass + ', age ' + (p.age == null ? 'unknown' : p.age) + '.';
}
$('go').onclick = run;
$('reset').onclick = () => { ['age', 'fare'].forEach(i => $(i).value = ''); $('title').value = 'Mr'; $('sex').value = 'male'; $('pclass').value = '3'; $('sibsp').value = 0; $('parch').value = 0; $('emb').value = 'S'; $('cabin').checked = false; $('res').style.display = 'none'; $('empty').style.display = 'block'; };
$('copy').onclick = async () => { try { await navigator.clipboard.writeText(last) } catch (e) { const t = document.createElement('textarea'); t.value = last; document.body.appendChild(t); t.select(); document.execCommand('copy'); t.remove() } $('copy').textContent = 'Copied!'; setTimeout(() => $('copy').textContent = 'Copy result', 1500); };
const EX = { a: { title: 'Mr', sex: 'male', age: '22', pclass: '3', sibsp: '0', parch: '0', fare: '7.25', emb: 'S', cabin: false }, b: { title: 'Mrs', sex: 'female', age: '35', pclass: '1', sibsp: '1', parch: '0', fare: '80', emb: 'C', cabin: true }, c: { title: 'Master', sex: 'male', age: '6', pclass: '2', sibsp: '1', parch: '1', fare: '26', emb: 'S', cabin: false } };
document.querySelectorAll('[data-ex]').forEach(b => b.onclick = () => { const e = EX[b.dataset.ex]; Object.keys(e).forEach(k => k === 'cabin' ? $('cabin').checked = e[k] : $(k).value = e[k]); run(); });
const chart = (id, obj, lab) => { $(id).innerHTML = Object.entries(obj).map(([k, [v, n]]) => `<div class="bar"><span>${lab ? lab[k] : k}</span><div class="t"><i style="width:${v}%"></i></div><b>${v}%</b></div>`).join('') + '<div class="note">Share of passengers who survived.</div>'; };
chart('c1', DATA.stats.sex, { male: 'Men', female: 'Women' }); chart('c2', DATA.stats.cls, { 1: '1st class', 2: '2nd class', 3: '3rd class' }); chart('c3', DATA.stats.age);
const NM = { Title_Mr: 'Title: Mr', Sex: 'Sex', Pclass: 'Ticket class', FamilySize: 'Family size', HasCabin: 'Has a cabin', Age: 'Age', Fare: 'Fare' };
const tp = Object.entries(DATA.imp).filter(([k]) => NM[k]).sort((a, b) => b[1] - a[1]), mx = tp[0][1];
$("imp").innerHTML = tp.map(([k, v]) => `<div class="bar"><span>${NM[k]}</span><div class="t"><i style="width:${v / mx * 100}%"></i></div><b>${Math.round(v * 100)}%</b></div>`).join('') + '<div class="note">Share of the model&rsquo;s decisions based on each fact.</div>';
$('theme').onclick = () => { const h = document.documentElement; h.dataset.theme = h.dataset.theme === 'dark' ? 'light' : 'dark'; };
$('menu').onclick = () => $('links').classList.toggle('open'); document.querySelectorAll('#links a').forEach(a => a.onclick = () => $('links').classList.remove('open'));
const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target) } }), { threshold: .1 }); document.querySelectorAll('.rv').forEach(e => io.observe(e));
function curve(p) { const x = buildFeatures(p); let s = 0; const o = [1 / (1 + Math.exp(-DATA.init))]; for (const t of DATA.trees) { let n = 0; while (t.l[n] !== -1) { n = x[t.f[n]] <= t.t[n] ? t.l[n] : t.r[n]; } s += t.v[n]; o.push(1 / (1 + Math.exp(-(DATA.init + DATA.lr * s)))); } return o; }
function drawCurve(p) {
    const c = curve(p), W = 520, H = 250, L = 40, B = 28, T = 12, R = 12, X = i => L + i / (c.length - 1) * (W - L - R), Y = v => T + (1 - v) * (H - T - B); let g = '';
    [0, .25, .5, .75, 1].forEach(v => g += `<line x1="${L}" x2="${W - R}" y1="${Y(v)}" y2="${Y(v)}" stroke="var(--line)"/><text x="${L - 6}" y="${Y(v) + 4}" text-anchor="end" font-size="10" fill="var(--mute)">${v * 100}%</text>`);
    [0, 50, 100, 150, 200].forEach(i => g += `<text x="${X(i)}" y="${H - 8}" text-anchor="${i === 200 ? 'end' : 'middle'}" font-size="10" fill="var(--mute)">${i} trees</text>`);
    const fin = c[c.length - 1], col = fin >= .5 ? 'var(--good)' : 'var(--bad)', d = c.map((v, i) => (i ? 'L' : 'M') + X(i).toFixed(1) + ' ' + Y(v).toFixed(1)).join('');
    $('curve').innerHTML = `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto" role="img" aria-label="Chance of survival as trees are added">${g}<line x1="${L}" x2="${W - R}" y1="${Y(.5)}" y2="${Y(.5)}" stroke="var(--mute)" stroke-dasharray="4 4"/><path d="${d}" fill="none" stroke="${col}" stroke-width="2.5"/><circle cx="${X(c.length - 1)}" cy="${Y(fin)}" r="5" fill="${col}"/></svg>`;
    $('curvenote').innerHTML = 'Starts at <b>' + Math.round(c[0] * 100) + '%</b> (average passenger) and ends at <b>' + Math.round(fin * 100) + '%</b> after all 200 trees.';
}
$('chk').innerHTML = DATA.check.map(r => { const w = Math.round(survivalChance(r.p) * 100); return `<tr><td>${r.name}</td><td>${r.py}%</td><td>${w}%</td><td class="ok">${w === r.py ? '&#10003; Match' : 'Check'}</td></tr>` }).join('');
drawCurve({ title: 'Mrs', sex: 'female', age: 35, pclass: 1, sibsp: 1, parch: 0, fare: 80, emb: 'C', cabin: 1 });